        'panda',
        'drools',
      ],
      [
        ['llama' => 'rocks', 'alpaca' => '', 'panda' => 'drools', 'z' => '0'],
        'z',
        '0',
      ],
      [
        ['llama' => 'rocks', 'alpaca' => '', 'panda' => 'drools', 'z' => '0'],
        'chicken',
        '',
      ],
      // Header value could be an array.
      [['z' => ['0', '1']], NULL, 'z=0,1'],
      // Values are sorted to minimize cache variations.
      [['z' => ['1', '0'], 'a' => []], NULL, 'a=&z=0,1'],
      [['a' => [], 'z' => ['1', '0']], NULL, 'a=&z=0,1'],
